INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U4 听力·短文 British Afternoon Tea', '必修二 U4 · passage', 2, 'Afternoon tea is an old British tradition that many families still enjoy.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (10, 'Introduce a Place, Festival or Tradition of the UK or China(介绍英国或中国的一个地方/节日/传统)', 'A Place I Want to Introduce', '假设你叫李华,一位外国笔友想了解你最喜欢的一个地方、节日或传统(英国或中国均可)。请用英语写一篇约100词的短文,内容包括:① 用一个醒目的画面、引语或问题开头,介绍这个地方/节日/传统是什么;② 用不同感官(看、听、闻、尝、触)描写细节;③ 说说它为什么重要或为什么打动你,并以有力的句子结尾。注意:可适当使用过去分词作定语/宾补(如 a well-organised festival / have the streets decorated)。', 'Suppose you are Li Hua. A foreign pen-friend wants to learn about your favourite place, festival or tradition (in the UK or China). Write a passage of about 100 words including: 1) an opening with a striking image, quote or question that says what it is; 2) sensory details (what you can see, hear, smell, taste or feel); 3) why it matters or moves you, with an effective ending. Try to use past participles as the attribute or object complement where natural.', '["醒目开头(A striking image / a question / introduce the place or tradition)","感官细节(see / hear / smell / taste / feel)","为什么重要或动人 + 有力结尾","适当用过去分词作定语/宾补(a well-organised festival / have the streets decorated)"]'::jsonb, 70, 100, 'Have you ever walked into a town that feels like a living history book? My favourite place is the ancient town of Pingyao in China. The first thing you see is the old city wall, surrounded by narrow stone streets dotted with red lanterns. You can hear the soft sound of festival music and smell the warm scent of local snacks. If you are lucky, you can taste a delicious bowl of stew in a small courtyard, with your eyes fixed on the beautiful old roofs. Pingyao matters to me because it keeps so many traditions alive. Walking through it really feels like walking into history.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Have you ever walked into a town that feels like a living history book?","The old city wall is surrounded by narrow streets dotted with red lanterns.","You can taste a delicious bowl of stew with your eyes fixed on the old roofs.","Pingyao matters to me because it keeps so many traditions alive."]'::jsonb, '[{"wrong":"The streets dotting with lanterns looked lovely.","correct":"The streets dotted with lanterns looked lovely.","note":"streets 被点缀,被动用过去分词 dotted,不用现在分词。"},{"wrong":"We had the streets decorating before the festival.","correct":"We had the streets decorated before the festival.","note":"have sth done:streets 被装饰,用过去分词 decorated。"},{"wrong":"I want introduce a place to you.","correct":"I want to introduce a place to you.","note":"want to do sth,want 后接动词不定式。"}]'::jsonb, '【介绍地方/节日/传统结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (10, 'required2', 'U4', '{"title":"过去分词作定语 & 作宾语补足语 速查","intro":"过去分词(done)表被动或完成。作定语时修饰名词(a broken window / soldiers wounded in the war);作宾语补足语时跟在 have/get/see/hear/find/want/make + 宾语后(get the car charged / heard it announced)。核心判断:宾语/名词与动作是被动关系→用过去分词,主动进行→用现在分词(doing)。","table":{"headers":["用法","结构 / 例句"],"rows":[["前置定语","单个分词修饰名词:a broken window / tired visitors / the shortened name"],["后置定语","分词带短语:soldiers wounded in the war / a lake surrounded by hills"],["have/get sth done","请人做或被完成:get the battery charged / had a copy boxed"],["感官/使役 + 宾 + done","see/hear/find/want/make:heard it announced / had her eyes fixed"]]},"specialRules":[{"rule":"名词/宾语承受动作(被动)→ 用过去分词 done","mark":"a broken window(窗户被打破)"},{"rule":"名词/宾语主动发出动作(主动·进行)→ 用现在分词 doing","mark":"a crying baby(婴儿在哭=主动)对照 a wounded soldier(士兵被伤)"},{"rule":"have/get sth done = 让别人做某事 / 某事被完成","mark":"get the car parked / have the photos printed"},{"rule":"see/hear/find/want + 宾 + done,强调宾语被动","mark":"heard it announced(它被宣布)"}],"why":["过去分词本身含被动、完成的意味,相当于一个被动的定语从句:soldiers wounded = soldiers who were wounded;heard it announced = heard that it was announced。宾语或名词是动作的承受者,所以不能用主动的 doing 或动词原形。"],"gaokaoPoints":["过去分词 vs 现在分词作定语/宾补:看名词或宾语是被动(done)还是主动(doing);语法填空、短文改错高频。","have/get sth done 与 have sb do sth 的区别:sth 被动用 done,sb 主动用 do/to do。"],"examVsReal":[{"exam":"I had my car repaired.(考试/书面)","real":"I got my car fixed.","note":"考试常用 have sth done;口语里 get sth done、用 fix 等更随意的词更常见"},{"exam":"soldiers wounded in the war（考试,后置定语）","real":"soldiers who got hurt in the war","note":"考试爱用过去分词短语;口语常还原成定语从句、用 get hurt"}]}'::jsonb);
